def add(kind,title,section='METHODS',evidence='SIMULATION / METHODS',sources=None,notes='',**kw):
 d=dict(id=f'S{len(S)+1:02}',kind=kind,title=title,section=section,evidence=evidence,sources=sources or [P],notes=notes,claims=[],**kw);S.append(d);return d

def text(title,paras,**kw):return add('text',title,paragraphs=paras,**kw)
def table(title,rows,caption='',**kw):return add('table',title,values=rows,caption=caption,**kw)
def flow(title,nodes,caption,**kw):return add('flow',title,nodes=nodes,caption=caption,**kw)
def video(title,file,poster,caption,**kw):return add('video',title,video=file,poster=poster,caption=caption,**kw)
def still(title,file,caption,**kw):return add('image',title,image='06_RIG_AND_MEDIA/stills/'+file+'.png',caption=caption,**kw)
text('GECO: evidence, intervention and recovery',['A reproducible simulation and methods study','Corrected prediction · matched comparisons · a measurable saline rig','IEEE-style research seminar | team and author details to be completed'],section='RESEARCH QUESTION',notes='Open with the practical question: when a system reports that it delivered something, what evidence would persuade us? GECOv6 is a research package, not an approved medical device. All numerical units are research model units. The IIT Patna rig is a proposal pending construction and measurement.')
text('The motivating question',['A permitted command and an accepted command do not prove fluid reached the outlet.','A monitor can reduce unwanted delivery while also interrupting wanted delivery.','The study measures both sides of intervention, including return to service.'],section='WHY THIS TOPIC',notes='Explain the three verbs: request, permit and emit. They name different events. Then explain the tradeoff in ordinary language: stopping a malfunction can help, but a stop that lasts too long also has a cost. Do not suggest the simulations establish patient benefit.')
flow('The evidence boundary',['Observation\nCGM or replay','Requested amount\ncontrol policy','Authorized amount\nlocal decision','Emitted amount\nactuator output','Measured evidence\nbalance indication','Received report\nmonitor input'],'Each link has its own value, timestamp, authority and possible failure.',section='WHY THIS TOPIC',notes='Trace the six boxes in order. A digital acknowledgment belongs near authorization; it must not be used as a substitute for emitted fluid. The experiment distinguishes local mass evidence from the network report, which matters when only the report is masked.')
text('The contribution to test',['An auditable chain from observations and commands to measurement and response.','A comparison that matches what each practical method can observe and control.','A release that preserves failures, censored recovery and model-domain violations.'],section='CONTRIBUTION',notes='The contribution is the accountable method and evidence separation. Prior work already includes insulin safety monitors, physiological models and gravimetric pump assessment. Do not claim the first digital twin, first safety monitor or first mass-sensing pump.')
table('What each evidence source can establish',[['Evidence','Supported use','Current limit'],['Supplied participant records','Internal forecast comparison','Previously exposed; not external validation'],['New synthetic trajectories','Paired intervention experiments','Depend on plant and actuator assumptions'],['Native rig animation','Explain proposed components and measurements','Conceptual, not an as-built rig'],['Future saline measurements','Physical measurement and stopping estimates','IIT Patna measurement pending']],section='EVIDENCE',notes='Keep these four evidence classes separate throughout the talk. The new simulated parameter vectors were unexamined before execution, but their physiological model structure is not independent clinical evidence.')
table('Corrections before new experiments',[['Problem','Repair','Validation'],['Uncertain covariance and gaps','Joseph update, finite and PSD guards, gap reset','Focused failure and timing tests'],['Prediction choice','Causal mechanistic, persistence and trend candidates','Fit/tune/test separation'],['Calibration path','One frozen runtime configuration; explicit failures','Configuration and execution receipts'],['Response accounting','Previous inputs; interval timing; actual emitted input','Independent trace recomputation']],notes='Describe what changed without calling the earlier numerical findings reliable. No predicted or authorized dose substitutes for the emitted input to the plant. Calibration infeasibility is a result to report, not a threshold to silently force.')
flow('Calibration and causal prediction',['Chronological fit\nfirst 50%','Tune candidate\nnext 25%','Freeze choices\nparameters + threshold','Test once\nlast 25%','Compare shared pairs\nsame due timestamps','Report failures\nno silent exclusions'],'Only information available at the prediction origin can enter that forecast.',sources=[F,P],notes='Parameter fitting uses the first chronological half; tuning uses the next quarter. The last quarter is an internal held-out segment of already supplied records. Forecasts are compared on identical due pairs. Offline interpolation upstream in supplied preprocessing limits strict claims about raw-data causality.')
a=json.loads((R/F).read_text());m=a['participant_median']
add('chart','Thirty-minute prediction error',section='PREDICTION RESULTS',categories=['Mechanistic','Persistence','Trend','Selected on tune'],series=[{'name':'Median participant RMSE (mg/dL)','values':[round(m[k],6) for k in ['mechanistic_rmse','persistence_rmse','trend_rmse','selected_rmse']]}],caption='31 participants; 77,110 shared pairs. Lower is better. Medians weight participants equally.',sources=[F],notes='Embedded chart values are rounded to6decimalplaces from the linked exact source; labels display1decimal. The selected model was trend for30 participants and persistence for1; none selected the mechanistic predictor. A median of selected participant errors is not the same as selecting the best method on the final test set.')
table('Prediction findings and limits',[['Finding','Estimate','Interpretation'],['Selected − persistence RMSE','−4.14 mg/dL; 95% CI −5.02 to −3.33','Paired participant bootstrap'],['Mechanistic versus persistence','Worse in 28 of 31 participants','Added structure did not ensure accuracy'],['Test union alarm burden','13 of 31 exceeded 1 episode/day','Tune budget did not generalize to all'],['Record disposition','31 evaluated; 2 excluded; 1 failed','Negative insulin entries caused explicit failure']],section='PREDICTION RESULTS',sources=[F,P],notes='Bootstrap intervals describe variation across these participants, not an external population guarantee. The median empirical95% forecast coverage was95.82%, ranging87.50–98.92%. Good median coverage conceals poor coverage for individual participants.24/31 fits approached parameter bounds; do not infer physiological identifiability.')
text('What this says about the model',['The mechanistic model was less accurate than persistence for most supplied participants.','The corrected pipeline therefore permits a simpler predictor selected before testing.','This is a limit of this model, implementation and dataset combination; it is not a verdict on every physiological model.'],section='PREDICTION RESULTS',sources=[F,P],notes='This is the plain-language answer to whether the model is “good.” A scientifically defensible model earns its role through comparison. Here the forecast evidence favors a trend or persistence fallback. Avoid referring to a vague “Jacob model”; distinguish the supplied mechanistic predictor from its numerical Jacobian.')
flow('Matched intervention experiments',['Shared reference\nrequest tape','Same meals + noise\npaired seed','Practical methods\nequal observations','Same local rules\nequal stop authority','Emitted amount\ndrives plant','Excess + deficit\ninterruption + recovery'],'Oracle uses evaluator-only fault timing and is reported as a privileged benchmark.',notes='The primary request tape is generated in a clean reference run and replayed into each arm. This isolates intervention under a common demand. Feedback-stopping sensitivity is separately reported. Practical methods share observation channels and local cutoffs; the oracle is deliberately privileged and cannot be treated as an implementable competitor.')
table('The primary experiment',[['Design choice','Frozen specification'],['Physiological plants','GECO original five-state; original Hovorka2004 equations'],['Test units','24 parameter vectors × 2 noise seeds per plant'],['Duration and disturbances','48h at5min; fault12–14h; eight conditions'],['Primary comparisons','Six response arms; 4,608 runs'],['Stop-model sensitivity','576 runs; 5,184 completed in total']],notes='The Hovorka implementation retains the published unclipped endogenous glucose production expression and logs domain failures. The48 runs per condition/arm are24 parameter vectors each paired over2 seeds. Confidence intervals resample parameter vectors after averaging paired seeds.')
table('Faults and observation assumptions',[['Condition','Injected change','Evidence retained'],['Excess / stuck-on','Actuator input doubled / added emission','Local and reported balance'],['Occlusion','No emission in fault window','Commands and local balance'],['Biased / missing CGM','+40mg/dL / absent report','Mass evidence and local rules'],['Combined excess + bias','Excess with +25mg/dL CGM bias','Local and reported mass'],['Masked network report','Combined fault; report substituted','Independent local mass remains']],notes='The factor2 is applied before quantization, gain, noise and dribble, so do not say exactly twice the emitted dose. Masked network reports do not compromise the independent local mass cutoff. This makes the model of remaining trusted evidence narrower than total sensor compromise.')
table('The six primary response arms',[['Arm','Monitor','Return to service'],['Full, manual','Mass CUSUM + physiological residuals','Scheduled manual release'],['Full, supervised','Same full detector','Probe and probation'],['Simple, manual','Instantaneous absolute mass residual','Scheduled manual release'],['Simple, supervised','Same simple detector','Probe and probation'],['Sham / oracle','Local rules only / known fault timing','Matched local rules / privileged timing']],notes='Full and simple differ in temporal aggregation as well as physiological input. Their difference alone cannot identify the incremental value of physiology. The separate exploratory fasting supplement adds a mass-CUSUM-only arm to address this component question.')
flow('Response and recovery states',['Running\nnormal authorization','Trip decision\nend of interval','Latched\nminimum 30min','Scheduled check\nevery 120min','Supervised probes\nthree capped amounts','Probation → running\nsix capped intervals'],'No catch-up delivery. Manual release and supervised recovery are separate comparisons.',notes='Trip timing is measured at the end of the triggering interval; stop effect is at the next interval in the primary model. Cooldown starts at that interval boundary. Supervised checks require current CGM and six quiet local readings; probe aggregate mass must meet the specified tolerance. The state before emission determines latch exposure. Guards remain active throughout probation.')
table('Outcomes that a stop can hide',[['Outcome','Definition','Reason to retain'],['Stepwise excess','Sum max(emitted − clean, 0)','Extra delivery cannot cancel a deficit'],['Stepwise deficit','Sum max(clean − emitted, 0)','A long stop remains visible'],['Longest interruption','Positive request; zero emission','Duration matters beyond total dose'],['Recovery onset / confirmation','First six good intervals / confirmation30min later','No single ambiguous recovery time'],['Censored recovery / domain flags','Retain failed outcomes and denominators','Failures remain in the denominator']],notes='All research-U quantities are simulated model amounts, not clinical dosing recommendations. The simulated reference is a clean model trajectory; in the physical work it must be replaced or qualified by a measured reference with an uncertainty budget.')
text('Primary experiment outcome',['5,184 runs completed without execution exceptions.','The full monitor did not show consistent superiority to the simpler monitor.','Independent review checked every full trace and recomputed core outcomes; all domain violations were retained.'],section='PRIMARY RESULTS',sources=[A,C,P],notes='Execution success means the specified software ran; it does not mean the model was physiologically valid.2,108 of4,608 main runs had domain violations, all in the Hovorka branch. This is a central limitation, not a footnote.')
table('Selected paired contrasts',[['Full supervised − simple supervised','Mean difference','95% paired CI'],['Original: stuck-on excess','+0.13745 research U','+0.10044 to +0.17445'],['Hovorka: stuck-on excess','+0.08458 research U','+0.04229 to +0.12688'],['Hovorka: occlusion deficit','+1.13031 research U','+0.13982 to +2.37804']],caption='Positive means more excess or deficit for the full monitor. Hovorka results are validity-limited.',section='PRIMARY RESULTS',sources=[C],notes='These are parameter-vector paired bootstrap contrasts, averaged across the2 seeds before resampling. They illustrate the central non-superiority finding; the full paper and machine-readable table contain every prespecified contrast. Hovorka comparisons cannot support credible clinical benefit because domain checks failed.')
table('Physiological validity audit',[['Branch','Clean practical comparison','Interpretation'],['Original model','0/48 clean trips for full and simple','No glucose-domain failure; action clamps remain'],['Original Hovorka equations','44/48 clean runs had negative EGP','Clean baseline already outside valid domain'],['Hovorka clean trips','Full2/48; simple0/48','False intervention did not disappear'],['Main Hovorka traces','2,108/2,304 had negative EGP','Intervention benefit claims are restricted']],section='PRIMARY RESULTS',sources=[A,P],notes='EGP is endogenous glucose production. Negative EGP in the retained equations is a physiological-domain violation. The original branch also reaches remote-action clamps, which must be disclosed. We preserve all traces and do not delete problematic units to produce a favorable claim.')
text('A separate validity and component check',['Exploratory follow-up after the primary model-domain failures.','New fasting parameter vectors and noise seeds; actuator-aware basal compensation.','Full, simple, mass-CUSUM-only and sham arms isolate a narrower component question.'],section='EXPLORATORY SUPPLEMENT',notes='Clearly distinguish this post-primary protocol from the originally frozen experiment. It removes meals and compensates the nominal actuator mapping analytically. It is not an external cohort, therapy validation or a retrospective repair of primary results. The final results slide is generated only from reviewed supplemental output.')
SU='03_EXPERIMENTS/supplement_fasting/'
table('Fasting supplement: validity and false stops',[['Finding','Locked exploratory result'],['Execution','2,048/2,048 completed; no failed runs'],['Physiological checks','0 domain-invalid and0 negative-EGP runs'],['Original clean trips','Full, mass-CUSUM and simple:3/32 each'],['Hovorka clean trips','Full3/32; mass-CUSUM and simple2/32'],['Interpretation','Declared screens passed; false stops remain']],section='EXPLORATORY SUPPLEMENT',sources=[SU+'RESULT_SUMMARY.json',SU+'ARM_SUMMARIES.json'],notes='Post-primary exploratory design;16new test parameter vectors per plant,2new noise seeds,8conditions and4supervised arms. Analytically selected actuator-aware fasting commands avoid the primary meal-driven domain failures. This does not validate meal responses or actual physiology. No unit or unsuccessful result was excluded. The original family still recorded18,648 remote-action clamp slots, including51 in clean runs; passing the screen is not physiological validation.')
