def readable(v):
 if isinstance(v,str):
  v=re.sub(r'(\d)([A-Za-z])',r'\1 \2',v)
  v=re.sub(r'\b(Full|full|simple|mass|Hovorka|for|at|of|with|over|first|all|and|next)(\d)',r'\1 \2',v)
  v=re.sub(r'\b([a-z]{2,})(\d)',r'\1 \2',v)
  v=re.sub(r';(?=\S)', '; ',v).replace('HUPA0027 P','HUPA0027P')
  return v
 if isinstance(v,list):return [readable(x) for x in v]
 return v
for d in S:
 for field in ['title','paragraphs','values','caption','notes','nodes','categories']:
  if field in d:d[field]=readable(d[field])
 d['sources']=[s for s in d['sources'] if (R/s).is_file()] or [P]
 d['source_hashes']={s:hashlib.sha256((R/s).read_bytes()).hexdigest() for s in d['sources']}
(O/'SLIDE_CONTENT.json').write_text(json.dumps(S,indent=2,ensure_ascii=False))
(O/'PRESENTER_SCRIPT.md').write_text('# GECOv6 presenter script\n\nA complete tour is eight minutes. Main slides can be presented selectively; technical appendix is optional. All media and assistance provenance are disclosed.\n\n'+'\n\n'.join(f"## {i}. {d['title']}\n\n{d['notes']}\n\nEvidence: {d['evidence']}. Sources: "+'; '.join(d['sources']) for i,d in enumerate(S,1)))
